/**
 * 地图下钻的纯计算部分：把「归一化坐标 + 容器尺寸 + 当前变换」换算成下一步变换。
 * 全部是纯函数，方便单测覆盖缩放焦点、包含式钳制等容易写错的地方。
 */

import { latToMercator, lngToMercator, normalizeLngLat, type GeoBounds } from '../../shared/geo';

export interface MapTransform {
  /** 缩放倍数，1 = 图片按 contain 铺满容器。 */
  scale: number;
  /** 相对基准位置的平移（容器像素）。 */
  x: number;
  y: number;
}

export interface Size {
  width: number;
  height: number;
}

export const IDENTITY_TRANSFORM: MapTransform = { scale: 1, x: 0, y: 0 };
export const MIN_MAP_SCALE = 1;
/**
 * 静态图底图的最大放大倍数。瓦片底图不用这个值：它的上限由底图自身的层级范围决定
 * （见 `scaleLimitsFor`），否则「一幅洪山区大小」的瓦片底图 baseZoom 只有 11 左右，
 * 固定 16 倍连 z15 都到不了，也就谈不上自由缩放。
 */
export const MAX_MAP_SCALE = 16;

export interface ScaleLimits {
  min: number;
  max: number;
}

export const IMAGE_SCALE_LIMITS: ScaleLimits = { min: MIN_MAP_SCALE, max: MAX_MAP_SCALE };

/**
 * 瓦片底图的缩放上限：正好够放大到 `maxZoom` 层级。
 * zoom = baseZoom + round(log2(scale))，所以 scale 取 2^(maxZoom-baseZoom) 就能到达最深层。
 */
export function scaleLimitsFor(minZoom: number, maxZoom: number, baseZoom: number): ScaleLimits {
  return { min: MIN_MAP_SCALE, max: Math.max(MIN_MAP_SCALE, 2 ** Math.max(0, maxZoom - baseZoom)) };
}

export function clampScale(scale: number, limits: ScaleLimits = IMAGE_SCALE_LIMITS): number {
  return Math.min(limits.max, Math.max(limits.min, scale));
}

/** 图片在容器内按 contain 摆放后的实际显示尺寸与左上角偏移。 */
export function fitContain(natural: Size, container: Size): { box: Size; origin: { x: number; y: number } } {
  if (!natural.width || !natural.height || !container.width || !container.height) {
    return { box: { width: 0, height: 0 }, origin: { x: 0, y: 0 } };
  }
  const ratio = Math.min(container.width / natural.width, container.height / natural.height);
  const width = natural.width * ratio;
  const height = natural.height * ratio;
  return {
    box: { width, height },
    origin: { x: (container.width - width) / 2, y: (container.height - height) / 2 },
  };
}

/**
 * 按 cover 摆放：铺满容器（多出来的部分由舞台裁掉），四周不留空白。
 * 地图（尤其瓦片底图）用这个，否则窄长/方形的范围会在宽屏上留出左右黑边。
 */
export function fitCover(natural: Size, container: Size): { box: Size; origin: { x: number; y: number } } {
  if (!natural.width || !natural.height || !container.width || !container.height) {
    return { box: { width: 0, height: 0 }, origin: { x: 0, y: 0 } };
  }
  const ratio = Math.max(container.width / natural.width, container.height / natural.height);
  const width = natural.width * ratio;
  const height = natural.height * ratio;
  return {
    box: { width, height },
    origin: { x: (container.width - width) / 2, y: (container.height - height) / 2 },
  };
}

/**
 * 以容器内的某一点为焦点缩放：焦点在缩放前后保持贴在同一个屏幕位置，
 * 这是滚轮/双指缩放“跟手”的关键。
 */
export function zoomAtPoint(
  current: MapTransform,
  factor: number,
  focus: { x: number; y: number },
  origin: { x: number; y: number },
  limits: ScaleLimits = IMAGE_SCALE_LIMITS,
): MapTransform {
  const scale = clampScale(current.scale * factor, limits);
  if (scale === current.scale) return current;
  const ratio = scale / current.scale;
  const ux = focus.x - origin.x;
  const uy = focus.y - origin.y;
  return {
    scale,
    x: ux - ratio * (ux - current.x),
    y: uy - ratio * (uy - current.y),
  };
}

/** 让图片上的归一化点在容器内居中（下钻动画的落点）。 */
export function centerOnPoint(
  point: { x: number; y: number },
  box: Size,
  container: Size,
  origin: { x: number; y: number },
  scale: number,
  limits: ScaleLimits = IMAGE_SCALE_LIMITS,
): MapTransform {
  const target = clampScale(scale, limits);
  return {
    scale: target,
    x: container.width / 2 - origin.x - point.x * box.width * target,
    y: container.height / 2 - origin.y - point.y * box.height * target,
  };
}

/**
 * 包含式钳制：放大到超过容器时不允许露出空白边，未超过时居中。
 * 避免用户把地图拖出视野后再也找不到。
 */
export function clampTransform(
  transform: MapTransform,
  box: Size,
  container: Size,
  origin: { x: number; y: number },
  limits: ScaleLimits = IMAGE_SCALE_LIMITS,
): MapTransform {
  const scale = clampScale(transform.scale, limits);
  const scaledWidth = box.width * scale;
  const scaledHeight = box.height * scale;
  return {
    scale,
    x: scaledWidth <= container.width
      ? (container.width - scaledWidth) / 2 - origin.x
      : Math.min(-origin.x, Math.max(container.width - origin.x - scaledWidth, transform.x)),
    y: scaledHeight <= container.height
      ? (container.height - scaledHeight) / 2 - origin.y
      : Math.min(-origin.y, Math.max(container.height - origin.y - scaledHeight, transform.y)),
  };
}

/** 下钻/进入全景前把标记推到画面中央并适度放大，形成“推近”的连续感。 */
export const DRILL_SCALE = 2.6;
export const DRILL_DURATION_MS = 340;

/* ------------------------------------------------------------------ *
 * 在线瓦片底图（XYZ / WMTS）的坐标换算。全部为纯函数，便于单测。
 * 约定：瓦片使用 Web Mercator（EPSG:3857）切片，与天地图/OSM/自建瓦片一致。
 * ------------------------------------------------------------------ */

export const TILE_SIZE = 256;
/**
 * 单帧最多渲染多少瓦片，防止配置错误导致一次拉取上百张图。
 * 这个值是**安全阀**而不是常规上限：正常一屏只渲染十几到几十张
 * （高分屏为了 1:1 清晰会多要一层，数量约 ×4）；只有配置写错（例如 bounds 远小于屏幕）才会撞到它。
 */
export const MAX_VISIBLE_TILES = 240;

export { latToMercator, lngToMercator, mercatorAspect, normalizeLngLat, type GeoBounds } from '../../shared/geo';

export interface TilePlacement {
  key: string;
  url: string;
  /** 相对底图的归一化矩形（0~1），直接乘底图尺寸即可定位。 */
  left: number;
  top: number;
  width: number;
  height: number;
  /** 标注/注记层：叠在底图之上。 */
  overlay?: boolean;
}

/** 让整幅范围大致铺满 targetPx 像素时的瓦片层级。 */
export function zoomForBounds(bounds: GeoBounds, targetPx: number): number {
  const span = lngToMercator(bounds.east) - lngToMercator(bounds.west);
  if (span <= 0 || targetPx <= 0) return 0;
  return Math.round(Math.log2(targetPx / (TILE_SIZE * span)));
}

/**
 * 让屏幕**横向正好覆盖 `meters` 米地面**所需的缩放倍数。
 *
 * 为什么需要它：只写 `zoom`（瓦片层级）时"每像素多少米"是固定的，
 * 屏幕越宽看到的地面就越多——实测手机 390px 上是 2.25 km、桌面 1302px 上是 5.63 km，
 * 同一个院区在两种屏幕上的大小差 2.5 倍。按横向跨度取景后，
 * 所有设备开场横向覆盖同样的距离，院区的视觉大小也就一致了。
 * （竖向可见范围仍随屏幕比例变化，这是无法回避的：竖屏必然看到更高的范围。）
 */
export function scaleForSpanMeters(
  meters: number,
  bounds: GeoBounds,
  centerLng: number,
  centerLat: number,
  box: Size,
  container: Size,
): number {
  if (!(meters > 0) || box.width <= 0 || container.width <= 0) return MIN_MAP_SCALE;
  const degreesPerMeter = 1 / (111_320 * Math.cos((centerLat * Math.PI) / 180));
  const half = (meters / 2) * degreesPerMeter;
  const west = normalizeLngLat(centerLng - half, centerLat, bounds).x;
  const east = normalizeLngLat(centerLng + half, centerLat, bounds).x;
  const spanPx = Math.abs(east - west) * box.width;
  return spanPx > 0 ? container.width / spanPx : MIN_MAP_SCALE;
}

/** 反过来：画面横向覆盖了多少米。页面内「设为默认视野」用它记下当前跨度。 */
export function spanMetersOf(normalizedWidth: number, bounds: GeoBounds, centerLat: number): number {
  return Math.abs(normalizedWidth) * (bounds.east - bounds.west) * 111_320 * Math.cos((centerLat * Math.PI) / 180);
}

/**
 * 当前变换下，容器里可见的那部分底图（归一化 0~1，可能超出范围，需再裁剪）。
 *
 * 必须带上 `origin`：底图元素定位在 `left/top = origin`，所以屏幕左上角对应的归一化坐标是
 * `(-origin.x - transform.x) / 缩放后宽度`。漏掉 origin 时（cover 摆放下 origin 通常为负，
 * 例如竖屏手机上左右各溢出 250px），取到的可见范围会整体偏移，屏幕一侧会拿不到瓦片而空白。
 */
export function visibleRect(
  transform: MapTransform,
  box: Size,
  container: Size,
  origin: { x: number; y: number } = { x: 0, y: 0 },
) {
  const scaledWidth = box.width * transform.scale;
  const scaledHeight = box.height * transform.scale;
  if (scaledWidth <= 0 || scaledHeight <= 0) return { x0: 0, y0: 0, x1: 1, y1: 1 };
  return {
    x0: (-origin.x - transform.x) / scaledWidth,
    y0: (-origin.y - transform.y) / scaledHeight,
    x1: (container.width - origin.x - transform.x) / scaledWidth,
    y1: (container.height - origin.y - transform.y) / scaledHeight,
  };
}

/** 屏幕坐标 → 底图归一化坐标（`visibleRect` 的逆运算，供页面内“点选位置”使用）。 */
export function normalizedFromScreen(
  screen: { x: number; y: number },
  transform: MapTransform,
  box: Size,
  origin: { x: number; y: number } = { x: 0, y: 0 },
): { x: number; y: number } {
  const scaledWidth = box.width * transform.scale;
  const scaledHeight = box.height * transform.scale;
  if (scaledWidth <= 0 || scaledHeight <= 0) return { x: 0.5, y: 0.5 };
  return {
    x: (screen.x - origin.x - transform.x) / scaledWidth,
    y: (screen.y - origin.y - transform.y) / scaledHeight,
  };
}

/**
 * 取当前可见区域覆盖到的瓦片。只算可见部分，因此再深的层级也只会渲染十几张。
 *
 * 子域名轮询（`subdomains`）有两种写法都支持：
 * - 模板里带 **`{s}`**（天地图 `t0`~`t7` 的标准写法）→ 直接替换占位符；
 * - 模板里写死 `t0`、只给 `subdomains` → 把主机名里的 `t<数字>` 换成选中的那台。
 *
 * 为什么第二种也要支持：`{s}` 只能由**新版前端**替换。如果访问者浏览器里还留着旧版 JS
 * （HTTP 缓存 / Service Worker 里 10 分钟内的旧 index.html），而配置已经更新成带 `{s}` 的版本，
 * 旧前端会把 `t{s}.tianditu.gov.cn` 这个字面量拼进 URL —— 整屏瓦片**全部**失败（一片碎图）。
 * 配置里写死一个真实主机名，任何版本的前端都能跑；轮询交给代码做，就没有这个窗口。
 */
export function tilesForViewport(
  bounds: GeoBounds,
  zoom: number,
  view: { x0: number; y0: number; x1: number; y1: number },
  template: string,
  subdomains: string[] = [],
): TilePlacement[] {
  const count = 2 ** zoom;
  const mercatorWest = lngToMercator(bounds.west);
  const mercatorEast = lngToMercator(bounds.east);
  const mercatorNorth = latToMercator(bounds.north);
  const mercatorSouth = latToMercator(bounds.south);
  const spanX = mercatorEast - mercatorWest;
  const spanY = mercatorSouth - mercatorNorth;
  if (spanX <= 0 || spanY <= 0) return [];

  const clamp01 = (value: number) => Math.max(0, Math.min(1, value));
  const toTileX = (normalized: number) => mercatorWest * count + spanX * count * normalized;
  const toTileY = (normalized: number) => mercatorNorth * count + spanY * count * normalized;
  /*
   * 索引要容忍浮点/配置取整误差：
   * - 左/上边界加 1e-6 个瓦片再取整，避免边界值算成 6697.9999999 时多要左边一列；
   * - 右/下边界用「上取整减一」并在取整前减同样的容差，避免边界正好落在瓦片线上时多要右边一列。
   * 多要的那一列在自建瓦片金字塔里并不存在（会 404 或回退成 index.html）。
   */
  const EDGE_EPSILON = 1e-6;
  const firstIndex = (value: number) => Math.floor(value + EDGE_EPSILON);
  const lastIndex = (value: number) => Math.ceil(value - EDGE_EPSILON) - 1;

  const firstX = Math.max(0, firstIndex(toTileX(clamp01(view.x0))));
  const lastX = Math.min(count - 1, lastIndex(toTileX(clamp01(view.x1))));
  const firstY = Math.max(0, firstIndex(toTileY(clamp01(view.y0))));
  const lastY = Math.min(count - 1, lastIndex(toTileY(clamp01(view.y1))));

  const tiles: TilePlacement[] = [];
  for (let x = firstX; x <= lastX; x += 1) {
    for (let y = firstY; y <= lastY; y += 1) {
      if (tiles.length >= MAX_VISIBLE_TILES) return tiles;
      // 用 (x + y) 做子域名分配：相邻瓦片落在不同域上，单域并发立刻降到 1/8。
      // 分配是**确定性**的（同一张瓦片永远同一台），所以轮询不会破坏缓存、平移回来不用重下。
      const subdomain = subdomains.length ? subdomains[(x + y) % subdomains.length] ?? '' : '';
      const filled = template
        .replace('{z}', String(zoom))
        .replace('{x}', String(x))
        .replace('{y}', String(y))
        .replace('{s}', subdomain);
      tiles.push({
        key: `${zoom}/${x}/${y}`,
        // 模板写死主机名（没有 {s}）时，把 `t<数字>.` 这一节换成选中的子域名。
        // 匹配不到就原样使用 —— 自建金字塔、其他厂商的模板都不受影响。
        url: template.includes('{s}') || !subdomain
          ? filled
          : filled.replace(/\/\/t\d+\./, `//t${subdomain}.`),
        left: (x / count - mercatorWest) / spanX,
        top: (y / count - mercatorNorth) / spanY,
        width: 1 / count / spanX,
        height: 1 / count / spanY,
      });
    }
  }
  return tiles;
}
