import { memo, useEffect, useRef, useState } from 'react';
import { enqueueTileRequest } from './tileQueue';

/** 瓦片取不到时的重试次数与起始退避（每次 ×2）。 */
const TILE_RETRIES = 3;
const TILE_RETRY_BASE_MS = 600;

/**
 * 一张瓦片：失败**必须重试**，不能像原来那样 `visibility: hidden` 一了百了。
 *
 * 上线反馈"iOS 上瓦片整片显示不出来"（截图里是一片蓝色问号）。实测取证（真实浏览器 + WebKit）：
 * - 一次进地图要发 **168 张瓦片请求**（DPR 3 的 iPhone 档位），单域突发极高；
 * - 天地图**只认 User-Agent**：裸请求 403 `Key权限类型为:浏览器端`，只加一个浏览器 UA 就 200，
 *   而 `Referer` / `Accept` / `Sec-Fetch-*` 三组头**都不是**判据（Safari 的 UA 也能通过）。
 *   所以"Referer 白名单"不是原因，不需要改 referrerPolicy（保持站点默认）。
 *
 * 每张瓦片优先在主源上重试三次；只有主源连续失败后才切 `fallbackUrl`。
 * 全局完成驱动队列（见 `tileQueue.ts`）将同时活动的图片请求限制为 8 张，
 * 避免 iOS 首屏请求突发压垮连接。
 *
 * 从 `MapPage.tsx` 原样搬出，行为一字未改。
 */
export const TileImage = memo(function TileImage(
  { url, fallbackUrl, className, style }:
  { url: string; fallbackUrl?: string; className: string; style: React.CSSProperties },
) {
  const imageRef = useRef<HTMLImageElement>(null);
  const releaseRequest = useRef<(() => void) | null>(null);
  const [attempt, setAttempt] = useState(0);
  const [onFallback, setOnFallback] = useState(false);
  const [failed, setFailed] = useState(false);
  const [hidden, setHidden] = useState(false);

  // 换 URL（缩放/平移后是另一批瓦片）时重置重试状态：新瓦片值得从头试。
  useEffect(() => { setAttempt(0); setOnFallback(false); setHidden(false); }, [url]);

  const source = onFallback && fallbackUrl ? fallbackUrl : url;
  /*
   * 首屏请求用原样 URL（便于浏览器缓存命中）；重试时带 `?r=N` 绕过 iOS 对失败响应的缓存
   * （实测天地图、Esri、高德都容忍这个多余参数），同时把 `t<数字>` 主机名换一台，
   * 免得一直撞同一个被限流的域（备用源没有 t0~t7，替换不中就只加参数）。
   */
  const src = attempt === 0
    ? source
    : (() => {
      const rotated = source.replace(/\/\/t(\d)\./, (_match, digit: string) => `//t${(Number(digit) + attempt) % 8}.`);
      return `${rotated}${rotated.includes('?') ? '&' : '?'}r=${attempt}`;
    })();

  useEffect(() => {
    let cancelled = false;
    const cancel = enqueueTileRequest(release => {
      const image = imageRef.current;
      if (cancelled || !image) { release(); return; }
      releaseRequest.current = release;
      image.src = src;
    }, onFallback);
    return () => {
      cancelled = true;
      cancel();
      releaseRequest.current?.();
      releaseRequest.current = null;
      imageRef.current?.removeAttribute('src');
    };
  }, [src, onFallback]);

  return (
    <img
      ref={imageRef}
      className={className}
      alt=""
      draggable={false}
      style={hidden || failed ? { ...style, visibility: 'hidden' } : style}
      onError={() => {
        releaseRequest.current?.();
        releaseRequest.current = null;
        setFailed(true);
        if (attempt < TILE_RETRIES) {
          const delay = TILE_RETRY_BASE_MS * 2 ** attempt;
          window.setTimeout(() => setAttempt(value => value + 1), delay);
          return;
        }
        // 保持主源优先；只有连续重试仍失败时才让备用源接管该瓦片。
        if (!onFallback && fallbackUrl) {
          setOnFallback(true);
          setAttempt(0);
          return;
        }
        setHidden(true);
      }}
      onLoad={() => {
        releaseRequest.current?.();
        releaseRequest.current = null;
        setFailed(false);
      }}
    />
  );
});
