import { forwardRef, useEffect, useImperativeHandle, useRef } from 'react';
import * as THREE from 'three';
import { RoomEnvironment } from 'three/examples/jsm/environments/RoomEnvironment.js';
import { activeScenePalette } from '../../shared/scenePalette';
import type { PlacementConfig, SiteModelConfig } from '../../config/schema';
import { enuFromLngLat, type LngLat } from '../../shared/geo';
import { disposeModelRoot } from '../devices/deviceModel';
import { placementTransform } from '../site/placement';
import { loadSiteModel } from '../site/siteModel';

/**
 * 把场地模型**嵌到地图上**（`docs/project/ROAM-PLAN-A.md` §2 S4b）。
 *
 * 与 `/site`（`SiteScene`）的区别：这里不自己铺瓦片——地图页本来就在画影像，
 * 这层只是一张**透明 WebGL 画布**盖在地图上方，用同一套「米」来对齐：
 *
 * - 场景坐标本身就是 ENU 米（`x` = 东、`-z` = 北），原点 = `placement.anchor`，
 *   而地图视野能给出「中心经纬 + 横向覆盖多少米」，于是正俯视时正交相机的
 *   `left/right/top/bottom` 直接就是地图那一块地面 —— 模型与影像逐点对齐；
 * - `tiltDeg > 0` 时改成透视相机从固定方向斜看**锚点**：模型立起来好看，
 *   但只有锚点那一点严格对齐（地图底图仍是正射影像，不会跟着倾）。
 *
 * 瓦片层级只决定**底图**多清楚；模型是真几何，缩到 `maxZoom` 之外依然清晰。
 * 手动定位：`placement` 的 heading / elevation / scale 由标定面板给（S3），
 * 地图上直接拖动改锚点是后续一步。
 */
export interface SiteOverlayView {
  /** 地图视野中心的经纬度。 */
  center: LngLat;
  /** 地图横向覆盖多少米（引擎的 `visibleSpan`）。 */
  spanMeters: number;
  /** 画布像素尺寸（= 地图容器尺寸）。 */
  width: number;
  height: number;
}

export interface SiteOverlayStats {
  ready: boolean;
  /** 模型是否已经进了场景。 */
  model: boolean;
  drawCalls: number;
  triangles: number;
  textures: number;
  spanMeters: number;
  /** 视野中心相对锚点的东/北偏移（米）——用来核对与地图是否同一套坐标。 */
  centerEast: number;
  centerNorth: number;
  /** 模型包围盒投影到画布的像素范围；不在画面里就是 null。 */
  screen: { left: number; top: number; right: number; bottom: number } | null;
  issues: number;
  errors: string[];
}

export interface SiteOverlay3DProps {
  site: SiteModelConfig;
  placement: PlacementConfig;
  view: SiteOverlayView | null;
  /** 俯仰角：0 = 正俯视（与影像对齐），>0 = 斜视（只有锚点对齐）。 */
  tiltDeg?: number;
  onStats?(stats: SiteOverlayStats): void;
}

const CAMERA_FAR = 8000;

/**
 * 命中测试句柄：给地图页一个「这一下到底点没点到模型上」的精确答案。
 *
 * 之前用投影包围盒的矩形判定，两个问题：① 矩形不是轮廓——模型是异形的，框角上是空地图，点那里也当命中；
 * ② `stats.screen` 只在**重画那一帧**才更新，而视野变化是去抖 140 ms 的，拖完地图立刻点会拿旧框去判，
 * 表现成「总是差一点」。射线求交用的是当下这台相机和真实几何，两个问题一起消掉。
 */
export interface SiteOverlay3DHandle {
  hitTest(clientX: number, clientY: number): boolean;
}

export const SiteOverlay3D = forwardRef<SiteOverlay3DHandle, SiteOverlay3DProps>(function SiteOverlay3D(
  { site, placement, view, tiltDeg = 0, onStats },
  ref,
) {
  const hostRef = useRef<HTMLDivElement>(null);
  const statsRef = useRef<SiteOverlayStats>({
    ready: false,
    model: false,
    drawCalls: 0,
    triangles: 0,
    textures: 0,
    spanMeters: 0,
    centerEast: 0,
    centerNorth: 0,
    screen: null,
    issues: 0,
    errors: [],
  });
  const sceneRef = useRef<{
    renderer: THREE.WebGLRenderer;
    scene: THREE.Scene;
    ortho: THREE.OrthographicCamera;
    perspective: THREE.PerspectiveCamera;
    modelRoot: THREE.Group;
    box: THREE.Box3;
  } | null>(null);
  const propsRef = useRef({ view, tiltDeg, onStats, placement, anchor: placement.anchor });
  propsRef.current = { view, tiltDeg, onStats, placement, anchor: placement.anchor };
  const drawRef = useRef<(() => void) | null>(null);
  const transformRef = useRef<(() => void) | null>(null);
  const raycasterRef = useRef(new THREE.Raycaster());

  useImperativeHandle(ref, () => ({
    hitTest(clientX: number, clientY: number) {
      const host = hostRef.current;
      const current = sceneRef.current;
      if (!host || !current || current.modelRoot.children.length === 0) return false;
      const rect = host.getBoundingClientRect();
      if (!rect.width || !rect.height) return false;
      // 视图矩阵可能是「改完视野还没重画」的旧值，射线前先把矩阵刷到当下。
      current.modelRoot.updateMatrixWorld(true);
      const pointer = new THREE.Vector2(
        ((clientX - rect.left) / rect.width) * 2 - 1,
        -(((clientY - rect.top) / rect.height) * 2 - 1),
      );
      const camera = propsRef.current.tiltDeg > 0.5 ? current.perspective : current.ortho;
      raycasterRef.current.setFromCamera(pointer, camera);
      return raycasterRef.current.intersectObject(current.modelRoot, true).length > 0;
    },
  }), []);

  /* 一次建场：渲染器、相机、模型。之后换视野只是重新摆相机再画一帧。 */
  useEffect(() => {
    const host = hostRef.current;
    const anchor = site.placement?.anchor;
    if (!host || !anchor) return;
    const palette = activeScenePalette();

    let renderer: THREE.WebGLRenderer;
    try {
      renderer = new THREE.WebGLRenderer({ alpha: true, antialias: true, powerPreference: 'high-performance' });
    } catch {
      statsRef.current.errors.push('无法启动三维查看器');
      propsRef.current.onStats?.({ ...statsRef.current });
      return;
    }
    renderer.setClearAlpha(0);
    renderer.outputColorSpace = THREE.SRGBColorSpace;
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = palette.site.exposure;
    renderer.domElement.className = 'map-site-overlay-canvas';
    // 手势必须穿透到地图：这一层只负责画，不接事件。
    renderer.domElement.style.pointerEvents = 'none';
    host.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    /*
     * 灯光与环境贴图必须与 `/site` 那套**一模一样**，否则同一个模型在两处一明一暗。
     * 之前这里只挂了两盏手调强度的灯：没有 `scene.environment`，PBR 材质的金属/高光没有
     * 任何可反射的东西，模型就成了一大片暗色剪影（用户反馈「模型是暗色的」就是这个原因）。
     */
    const pmrem = new THREE.PMREMGenerator(renderer);
    const room = new RoomEnvironment();
    const environment = pmrem.fromScene(room, 0.05);
    scene.environment = environment.texture;
    scene.environmentIntensity = palette.site.environmentIntensity;
    scene.add(new THREE.HemisphereLight(palette.site.hemisphere.sky, palette.site.hemisphere.ground, palette.site.hemisphere.intensity));
    const key = new THREE.DirectionalLight(palette.site.key.color, palette.site.key.intensity);
    key.position.set(...palette.site.key.position);
    scene.add(key);
    const fill = new THREE.DirectionalLight(palette.site.fill.color, palette.site.fill.intensity);
    fill.position.set(...palette.site.fill.position);
    scene.add(fill);

    const ortho = new THREE.OrthographicCamera(-1, 1, 1, -1, 0.1, CAMERA_FAR);
    ortho.up.set(0, 0, -1);
    const perspective = new THREE.PerspectiveCamera(42, 1, 0.5, CAMERA_FAR);
    const modelRoot = new THREE.Group();
    scene.add(modelRoot);
    const box = new THREE.Box3();
    const state = { renderer, scene, ortho, perspective, modelRoot, box };
    sceneRef.current = state;
    statsRef.current.ready = true;

    let disposed = false;
    let model: THREE.Object3D | null = null;

    /**
     * 把 `placement`（标定面板正在拖的那组数）贴到模型上。
     * 单独拎出来是为了让标定时**不必重建 WebGL**：滑杆一动，重摆一下模型再画一帧。
     */
    function applyTransform() {
      if (!model) return;
      const transform = placementTransform(propsRef.current.placement);
      model.position.set(...transform.position);
      model.rotation.y = transform.rotationY;
      model.scale.setScalar(transform.scale);
      model.updateMatrixWorld(true);
      box.setFromObject(modelRoot);
    }

    loadSiteModel(site, {
      onProgress: () => undefined,
    }).then(loaded => {
      if (disposed) {
        disposeModelRoot(loaded.root);
        return;
      }
      model = loaded.root;
      modelRoot.add(loaded.root);
      applyTransform();
      statsRef.current.model = true;
      statsRef.current.issues = loaded.issues.length;
      draw();
    }).catch((error: unknown) => {
      if (disposed) return;
      statsRef.current.errors.push(error instanceof Error ? error.message : String(error));
      propsRef.current.onStats?.({ ...statsRef.current });
    });

    /** 按当前视野摆相机并画一帧。 */
    function draw() {
      const current = sceneRef.current;
      const { view: next, tiltDeg: tilt, onStats: report } = propsRef.current;
      if (!current || !next || disposed) return;
      const width = Math.max(1, Math.round(next.width));
      const height = Math.max(1, Math.round(next.height));
      current.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 1.5));
      current.renderer.setSize(width, height, false);

      // 锚点每帧取**当前**的 `placement`（手动定位会一边拖一边改它），不能用挂载时捕获的旧值。
      const anchorNow = propsRef.current.anchor;
      if (!anchorNow) return;
      const enu = enuFromLngLat(anchorNow, next.center);
      const span = Math.max(1, next.spanMeters);
      const heightMeters = span * (height / width);
      const centerY = current.box.isEmpty() ? 0 : (current.box.min.y + current.box.max.y) / 2;
      let active: THREE.Camera = current.ortho;

      if (tilt > 0.5) {
        // 斜视：从锚点正南偏东的方向看向锚点。只保证锚点对齐，模型立起来。
        const radians = THREE.MathUtils.degToRad(tilt);
        const distance = Math.max(span, 60) * 1.35;
        current.perspective.aspect = width / height;
        current.perspective.position.set(
          enu.east + Math.sin(radians) * distance * 0.55,
          Math.max(8, centerY) + Math.cos(radians) * distance,
          -enu.north + Math.cos(radians) * distance * 0.55,
        );
        current.perspective.lookAt(enu.east, Math.max(0, centerY * 0.6), -enu.north);
        current.perspective.updateProjectionMatrix();
        active = current.perspective;
      } else {
        current.ortho.left = -span / 2;
        current.ortho.right = span / 2;
        current.ortho.top = heightMeters / 2;
        current.ortho.bottom = -heightMeters / 2;
        current.ortho.position.set(enu.east, CAMERA_FAR * 0.5, -enu.north);
        current.ortho.lookAt(enu.east, 0, -enu.north);
        current.ortho.updateProjectionMatrix();
      }

      current.renderer.render(current.scene, active);

      const stats = statsRef.current;
      stats.spanMeters = span;
      stats.centerEast = enu.east;
      stats.centerNorth = enu.north;
      stats.drawCalls = current.renderer.info.render.calls;
      stats.triangles = current.renderer.info.render.triangles;
      stats.textures = current.renderer.info.memory.textures;
      /*
       * 统一成 **CSS 像素**：`screenBounds` 算的是设备像素（画布后备尺寸 = CSS × pixelRatio），
       * 而指针事件、`view.spanMeters / view.width` 都在 CSS 像素里。混着用会让「跟手」差一个倍率。
       */
      const ratio = current.renderer.getPixelRatio();
      stats.screen = screenBounds(current.box, active, width / ratio, height / ratio);
      report?.({ ...stats });
    }

    // 探针入口：`?perf=1` 时把渲染器挂到 window，`probe-ground.mjs` 一类的脚本可以直接读。
    if (new URLSearchParams(window.location.search).get('perf') === '1') {
      (window as unknown as { __museumOverlay?: unknown }).__museumOverlay = { renderer, scene, modelRoot, stats: statsRef.current };
    }

    drawRef.current = draw;
    transformRef.current = applyTransform;
    draw();
    return () => {
      disposed = true;
      drawRef.current = null;
      transformRef.current = null;
      sceneRef.current = null;
      statsRef.current.ready = false;
      statsRef.current.model = false;
      for (const child of [...modelRoot.children]) {
        modelRoot.remove(child);
        disposeModelRoot(child);
      }
      environment.dispose();
      pmrem.dispose();
      renderer.dispose();
      renderer.domElement.remove();
    };
    // 场地配置（模型文件、锚点）换了才重建；视野与标定值走上面那个 effect。
  }, [site]);

  /*
   * 视野 / 俯仰角 / 标定值变了：重摆模型再画一帧（不重建 WebGL）。
   *
   * **合并成「停下来再画」**：这块场地模型是 940 万三角面 / 400+ draw call，
   * 拖动地图时逐帧重画会把主线程吃光（地图自己的瓦片层是 CSS 缩放，本来很便宜）。
   * 所以手势过程中模型保持上一帧，停手 140 ms 后一次画到位。
   */
  useEffect(() => {
    const timer = window.setTimeout(() => {
      transformRef.current?.();
      drawRef.current?.();
    }, 140);
    return () => window.clearTimeout(timer);
  }, [view, tiltDeg, placement]);

  return <div className="map-site-overlay" ref={hostRef} data-testid="map-site-overlay" aria-hidden="true" />;
});

/** 世界包围盒投影到画布像素（探针用它证明「模型真的在画面里、落在哪个像素范围」）。 */
function screenBounds(box: THREE.Box3, camera: THREE.Camera, width: number, height: number) {
  if (box.isEmpty()) return null;
  camera.updateMatrixWorld();
  let left = Infinity;
  let top = Infinity;
  let right = -Infinity;
  let bottom = -Infinity;
  const point = new THREE.Vector3();
  for (let i = 0; i < 8; i += 1) {
    point.set(
      i & 1 ? box.max.x : box.min.x,
      i & 2 ? box.max.y : box.min.y,
      i & 4 ? box.max.z : box.min.z,
    );
    // 包围盒是**世界**坐标（`setFromObject(modelRoot)`），`modelRoot` 本身在原点，直接投影。
    point.project(camera);
    const x = (point.x * 0.5 + 0.5) * width;
    const y = (0.5 - point.y * 0.5) * height;
    left = Math.min(left, x);
    right = Math.max(right, x);
    top = Math.min(top, y);
    bottom = Math.max(bottom, y);
  }
  return { left, top, right, bottom };
}
