/**
 * 瓦片请求队列（完成驱动，全页共用一个）。
 *
 * 时间分批仍会在慢网络下堆满连接，这里硬限制同时加载数：一张瓦片加载完才放下一张进来。
 * 从 `MapPage.tsx` 原样搬出，行为一字未改 —— 新地图壳与旧地图页共用同一条队列，
 * 否则两个页面各自限流 8 张，同时挂载时会把同一 host 的连接数挤爆。
 */

/** 同时活动的瓦片请求上限。 */
export const MAX_ACTIVE_TILE_REQUESTS = 8;

type TileRequest = { start: (release: () => void) => void; cancelled: boolean; release?: () => void };

const pendingTileRequests: TileRequest[] = [];
let activeTileRequests = 0;

function pumpTileRequests() {
  while (activeTileRequests < MAX_ACTIVE_TILE_REQUESTS && pendingTileRequests.length > 0) {
    const request = pendingTileRequests.shift()!;
    if (request.cancelled) continue;
    activeTileRequests += 1;
    let released = false;
    const release = () => {
      if (released) return;
      released = true;
      activeTileRequests -= 1;
      request.release = undefined;
      pumpTileRequests();
    };
    request.release = release;
    request.start(release);
  }
}

/**
 * 排队一次瓦片加载，返回取消函数。
 * `priority` 用于重试与备用源——它们比新瓦片更值得先发。
 */
export function enqueueTileRequest(start: TileRequest['start'], priority = false) {
  const request: TileRequest = { start, cancelled: false };
  if (priority) pendingTileRequests.unshift(request);
  else pendingTileRequests.push(request);
  pumpTileRequests();
  return () => {
    request.cancelled = true;
    const index = pendingTileRequests.indexOf(request);
    if (index >= 0) pendingTileRequests.splice(index, 1);
    request.release?.();
  };
}
