import { forwardRef, useImperativeHandle, useRef, useState } from 'react';
import type { OrthoOverlayConfig } from '../../config/schema';
import type { LngLat } from '../../shared/geo';
import { orthoOverlayRect, overlayImagePoint, overlayRectContains, type MapOverlayView, type OverlayRect } from './orthoOverlay';

/**
 * 地图上的场地层：一张**离线烘焙的正射贴图**，钉在地理坐标上。
 *
 * 为什么不用实时三维（`SiteOverlay3D`，仍在仓库里做后备）：那层每帧要画 910 万面、400+ draw call，
 * 拖动地图时只能 140ms 防抖"停下来再画"，手指下就是一顿一顿的（现场 2026-10-19 反馈：手机/平板
 * 拖动卡顿）。换成一张位图后，拖动只是移动一个 `<img>`：`transform` 交给合成器，主线程不参与画模型。
 *
 * 摆位算术全在 `orthoOverlay.ts`（纯函数、有单测）；这里只负责：
 * 1. 用 `transform: translate3d(...) scale(...)` 摆放——不用 `left/top`，那是每帧重排+重绘；
 *    `will-change: transform` 把位图提升成合成层，平移时浏览器不重新栅格化。
 * 2. `hitTest()`：按贴图的 alpha 判断"这一点到底在不在模型上"（图上四角是透明的，
 *    包围盒判定会把空白处也当成模型），供"点模型进场地"用。
 */
export interface SiteOverlayFlatHandle {
  /** 屏幕坐标（clientX/clientY）落在贴图**不透明**处才为真。 */
  hitTest(clientX: number, clientY: number): boolean;
}

export interface SiteOverlayFlatProps {
  /** 已解析成可访问路径的贴图地址。 */
  image: string;
  ortho: OrthoOverlayConfig;
  /** 地理锚点（`siteModel.placement.anchor`）。 */
  anchor: LngLat;
  /** 地图当前视野：中心经纬 + 横向覆盖米数 + 画布 CSS 尺寸。 */
  view: MapOverlayView;
  /** 透明度（`siteModel.ground.overlayOpacity`）。 */
  opacity: number;
}

/** 查 alpha 用的位图上限：只要形状对，缩到这个尺寸足够判"在不在模型上"。 */
const MASK_MAX_EDGE = 512;
/** 图上 alpha 大于它才算"实心"（抗锯齿边缘会有很淡的像素）。 */
const MASK_ALPHA_THRESHOLD = 8;

export const SiteOverlayFlat = forwardRef<SiteOverlayFlatHandle, SiteOverlayFlatProps>(function SiteOverlayFlat(
  { image, ortho, anchor, view, opacity },
  ref,
) {
  const hostRef = useRef<HTMLDivElement>(null);
  const rectRef = useRef<OverlayRect | null>(null);
  const maskRef = useRef<{ data: Uint8ClampedArray; width: number; height: number } | null>(null);
  /** 图片真的画出来了；没画出来（404/被墙）就不该把点击算成"点在模型上"。 */
  const loadedRef = useRef(false);
  const [natural, setNatural] = useState<{ width: number; height: number } | null>(null);

  const rect = orthoOverlayRect(ortho, anchor, view);
  rectRef.current = rect;

  /** 用缩小后的副本建 alpha 蒙版；跨域被污染时放弃（退回矩形判定）。 */
  const buildMask = (node: HTMLImageElement) => {
    if (node.naturalWidth <= 0 || node.naturalHeight <= 0) return;
    const scale = Math.min(1, MASK_MAX_EDGE / Math.max(node.naturalWidth, node.naturalHeight));
    const width = Math.max(1, Math.round(node.naturalWidth * scale));
    const height = Math.max(1, Math.round(node.naturalHeight * scale));
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const context = canvas.getContext('2d', { willReadFrequently: true });
    if (!context) return;
    context.drawImage(node, 0, 0, width, height);
    try {
      const pixels = context.getImageData(0, 0, width, height);
      // 用回读到的尺寸（而不是请求的尺寸）：蒙版是自描述的，换算时不会错位。
      maskRef.current = { data: pixels.data, width: pixels.width, height: pixels.height };
    } catch {
      // 贴图来自没有 CORS 头的 CDN 时会抛：这时只能按包围盒判定。
      maskRef.current = null;
    }
  };

  useImperativeHandle(ref, () => ({
    hitTest(clientX: number, clientY: number) {
      const host = hostRef.current;
      if (!host || !loadedRef.current) return false;
      const stage = host.getBoundingClientRect();
      const x = clientX - stage.left;
      const y = clientY - stage.top;
      const box = rectRef.current;
      if (!overlayRectContains(box, x, y)) return false;
      const mask = maskRef.current;
      if (!mask) return true; // 拿不到像素就按矩形算（至少知道贴图已经加载出来了）。
      const point = overlayImagePoint(box, mask.width, mask.height, x, y);
      if (!point) return false;
      const px = Math.min(mask.width - 1, Math.max(0, Math.floor(point.x)));
      const py = Math.min(mask.height - 1, Math.max(0, Math.floor(point.y)));
      return (mask.data[(py * mask.width + px) * 4 + 3] ?? 0) > MASK_ALPHA_THRESHOLD;
    },
  }));

  if (!rect) return null;

  return (
    <div className="map-site-overlay" ref={hostRef} data-testid="map-site-overlay" aria-hidden="true">
      <img
        className="map-site-overlay-image"
        src={image}
        alt=""
        draggable={false}
        data-testid="map-site-overlay-image"
        onLoad={event => {
          const node = event.currentTarget;
          loadedRef.current = true;
          setNatural({ width: node.naturalWidth, height: node.naturalHeight });
          buildMask(node);
          warnOnAspectMismatch(ortho, node);
        }}
        style={
          natural && natural.width > 0
            ? {
                width: `${natural.width}px`,
                height: `${natural.height}px`,
                // 一个矩阵搞定：先缩到"米/像素"对应的尺寸，再挪到贴图西北角。
                transform: `translate3d(${rect.left}px, ${rect.top}px, 0) scale(${rect.width / natural.width})`,
                opacity,
              }
            : { visibility: 'hidden' }
        }
      />
    </div>
  );
});

/**
 * 贴图长宽比与配置里的米数不一致说明有人改了图没改配置（会看出拉伸）。
 * 只在开发期提醒，线上不打扰。
 */
export function warnOnAspectMismatch(
  ortho: OrthoOverlayConfig,
  image: { naturalWidth: number; naturalHeight: number },
): void {
  if (!import.meta.env.DEV) return;
  if (image.naturalWidth <= 0 || image.naturalHeight <= 0) return;
  const imageAspect = image.naturalWidth / image.naturalHeight;
  const configAspect = ortho.widthMeters / ortho.heightMeters;
  if (Math.abs(imageAspect - configAspect) / configAspect > 0.02) {
    console.warn(
      `[map] 正射贴图长宽比 ${imageAspect.toFixed(4)} 与配置 ${configAspect.toFixed(4)} 不一致，画面会被拉伸`,
    );
  }
}
